/**
 * The seat count every plan check compares against. Suspended members keep
 * their seat; a removed member is archived and does not.
 */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        or(eq(members.status, "active"), eq(members.status, "suspended")),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * A removed member is archived, so this is false for them: suspension is a
 * live membership whose status is `suspended`, not a soft delete.
 */
export async function isSuspendedMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await findMember(orgId, userId);
  return member !== null && member.status === "suspended";
}

export async function setMemberStatus(
  orgId: OrgId,
  memberId: MemberId,
  status: MemberStatus,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ status, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        isNull(members.archivedAt),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

