/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner who is not suspended. A suspended owner does not keep the
 * workspace ownable. Exported because demote, remove and suspend all share it.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter(
    (row) => row.id !== memberId && row.status !== "suspended",
  );
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

/**
 * Shared guards for suspend and reinstate: tenant scope, a live membership,
 * `member:remove`, and the rule that you cannot touch yourself or a role
 * that outranks yours. A removed member is not suspended — it is missing.
 */
async function requireSuspendableMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
  verb: "suspend" | "reinstate",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }

  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error(`You cannot ${verb} yourself`);
  }

  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot ${verb} a ${member.role}`);
  }

  return member;
}

