    expect(await resolveActor(tenant.userIds.member, tenant.org.id)).not.toBeNull();
    expect((await orgRepo.listOrgsForUser(tenant.userIds.member)).map((org) => org.id)).toContain(
      tenant.org.id,
    );

    off();
    off2();
  });

  it("refuses self, outranked, last owner, missing, removed, and cross-tenant", async () => {
    const tenant = await createTenant("suspend-guards", "growth");
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!owner || !admin || !viewer) throw new Error("missing");

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/yourself/);
    expect((await memberRepo.findMemberById(tenant.org.id, owner.id))?.status).toBe("active");

    await expect(
      suspendMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/cannot suspend/);
    expect((await memberRepo.findMemberById(tenant.org.id, owner.id))?.status).toBe("active");

    await expect(
      suspendMember(tenant.actors.member, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id }),
    ).rejects.toThrow(/yourself/);

    const other = await createTenant("suspend-other", "growth");
    await expect(
      suspendMember(tenant.actors.owner, { orgId: other.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "mem_missing" as never,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await memberRepo.archiveMember(tenant.org.id, viewer.id);
    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(3);

    await memberServicePromoteSecondOwner(tenant);
    const suspendedOwner = await suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: owner.id,
    });
    expect(suspendedOwner.status).toBe("suspended");

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id }),
    ).rejects.toThrow(/at least one owner/);

    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(await memberRepo.countActiveMembers(tenant.org.id));
    expect(usage.seatsUsed).toBe(4);
  });

  it("records an audit row", async () => {
    const tenant = await createTenant("suspend-audit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");
    const detach = registerActivityListeners();
    await suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    const page = await import("@/server/repositories/activity-repository").then((mod) =>
      mod.listActivity({ orgId: tenant.org.id, limit: 20, cursor: null }),
    );
    expect(page.items.some((row) => row.action === "member.suspended" && row.subjectId === target.id)).toBe(
      true,
    );
    detach();
    void notificationRepo;
  });
});

async function memberServicePromoteSecondOwner(tenant: {
  org: { id: import("@/types/common").OrgId };
  actors: { owner: import("@/types/member").Actor; admin: import("@/types/member").Actor };
  userIds: { admin: import("@/types/common").UserId };
}): Promise<void> {
  const { updateMemberRole } = await import("@/server/services/member-service");
  const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
  if (!admin) throw new Error("missing admin");
  await updateMemberRole(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: admin.id,
    role: "owner",
  });
}
