import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as issueService from "@/server/services/issue-service";
import {
  MemberSuspendedError,
  reinstateMember,
  resolveActor,
  suspendMember,
  updateMemberRole,
} from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import type { Actor } from "@/types/member";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("suspension", () => {
  it("suspends, keeps the seat, hides the org, blocks work, then reinstates", async () => {
    const tenant = await createTenant("suspend-flow", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("missing");
    const beforeSeats = await memberRepo.countActiveMembers(tenant.org.id);

    const events: string[] = [];
    const off = subscribe("member.suspended", () => events.push("suspended"));
    const off2 = subscribe("member.reinstated", () => events.push("reinstated"));

    const suspended = await suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(suspended.archivedAt).toBeNull();

    const again = await suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(again.status).toBe("suspended");
    expect(events).toEqual(["suspended"]);

    expect(await resolveActor(tenant.userIds.member, tenant.org.id)).toBeNull();
    expect((await orgRepo.listOrgsForUser(tenant.userIds.member)).map((org) => org.id)).not.toContain(
      tenant.org.id,
    );

    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(beforeSeats);
    const listed = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(listed.items.find((row) => row.id === target.id)?.status).toBe("suspended");

    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Do not assign",
          assigneeId: tenant.userIds.member,
        }),
      ),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(0);

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Unassigned work" }),
    );
    await issueRepo.setIssueAssignee(tenant.org.id, issue.id, tenant.userIds.member);
    await expect(
      issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.assigneeId).toBe(
      tenant.userIds.member,
    );

    const unassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });
    expect(unassigned.assigneeId).toBeNull();

    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });
    expect(assigned.assigneeId).toBe(tenant.userIds.admin);

    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @member",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.member);

    const notes = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "ping",
        body: "ping",
        href: "/issues/1",
        actorId: tenant.userIds.owner,
      },
    );
    expect(notes.map((row) => row.recipientId)).toEqual([tenant.userIds.admin]);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: true,
    });
    expect(await listDigestRecipients(tenant.org.id)).not.toContain(tenant.userIds.member);
    expect(
      await buildDigest(
        tenant.org.id,
        tenant.userIds.member,
        tenant.org.createdAt,
        toIsoTimestamp(new Date(Date.now() + 86_400_000)),
