      suspendMember(tenant.actors.owner, { orgId: other.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "mem_missing" as never,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await memberRepo.archiveMember(tenant.org.id, viewer.id);
    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await memberRepo.isSuspendedMember(tenant.org.id, tenant.userIds.viewer)).toBe(false);
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(3);

    await updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });
    const promoted: Actor = { ...tenant.actors.admin, role: "owner" };
    const suspendedOwner = await suspendMember(promoted, {
      orgId: tenant.org.id,
      memberId: owner.id,
    });
    expect(suspendedOwner.status).toBe("suspended");

    await expect(
      suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      updateMemberRole(promoted, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);

    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(3);
    expect(usage.seatsUsed).toBe(await memberRepo.countActiveMembers(tenant.org.id));
  });

  it("records an audit row for suspend and reinstate", async () => {
    const tenant = await createTenant("suspend-audit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("missing");
    const detach = registerActivityListeners();
    try {
      await suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
      await reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
      const page = await activityRepo.listActivity({
        orgId: tenant.org.id,
        limit: 20,
        cursor: null,
      });
      const actions = page.items
        .filter((row) => row.subjectId === target.id)
        .map((row) => row.action);
      expect(actions).toEqual(expect.arrayContaining(["member.suspended", "member.reinstated"]));
      const suspendedRow = page.items.find((row) => row.action === "member.suspended");
      expect(suspendedRow?.subjectKind).toBe("member");
      expect(suspendedRow?.actorId).toBe(tenant.userIds.owner);
    } finally {
      detach();
    }
  });
});

